1	/**
2	 * @file looper.cpp
3	 * @brief D-Bus 事件循环实现（单例 Looper）
4	 *
5	 * Looper 是 D-Bus 消息派发的核心驱动。D-Bus 本身不启动线程，
6	 * 所有消息处理都必须在调用 dbus_connection_read_write_dispatch
7	 * 的线程上完成。本文件实现的就是这个"唯一的 D-Bus 线程"。
8	 *
9	 * 两种运行模式：
10	 *   1. poll 模式（推荐）：同时监听 D-Bus fd 和 signal pipe
11	 *      - 通过 self-pipe trick 解决信号中断问题
12	 *      - 100ms 超时快速响应外部状态变化
13	 *   2. timeout 模式（降级）：pipe 创建失败时使用
14	 *      - 依赖 dbus_connection_read_write_dispatch(conn_, 1000) 的 1 秒超时
15	 *      - 需要 Logger::stopRequested() 配合（signal handler 标记 stop）
16	 *
17	 * self-pipe trick 设计原理：
18	 *   原始 signal handler 只能设置 volatile flag，但 dbus_connection_read_write_dispatch
19	 *   可能阻塞在 poll/select 上看不到 flag 变化。解法是创建 pipe，
20	 *   signal handler 写一端，事件循环 poll 读一端，这样信号能立即唤醒 poll。
21	 */
22	
23	#include <dbus/dbus.h>
24	#include <poll.h>
25	#include <unistd.h>
26	#include <fcntl.h>
27	#include <signal.h>
28	#include <memory>
29	#include <cerrno>
30	
31	#include "server.hpp"
32	#include "looper.hpp"
33	#include "logger.hpp"
34	
35	namespace weaknet_dbus {
36	
37	/// 每个线程独立的 Looper 实例（单例 + thread_local）
38	static thread_local std::unique_ptr<Looper> t_looper;
39	
40	/**
41	 * @brief self-pipe：signal handler 写一端，poll 循环读另一端
42	 *
43	 * 为什么用 pipe 而不是 volatile flag？
44	 *   dbus_connection_read_write_dispatch() 内部可能阻塞在 poll/epoll_wait 上，
45	 *   flag 设置后 poll 不会返回，事件循环收不到信号。
46	 *   pipe 写入会让 poll 的 POLLIN 立即触发，保证信号不丢失。
47	 *
48	 * 为什么 signal handler 里能用 write()？
49	 *   write() 是 POSIX async-signal-safe 函数，signal handler 中可以安全调用。
50	 *   我们只写 1 字节，几乎不会阻塞（pipe 缓冲区通常 4KB）。
51	 */
52	static int s_stop_pipe[2] = {-1, -1};
53	
54	/**
55	 * @brief SIGTERM/SIGINT 处理器：写 pipe 通知 Looper 退出
56	 *
57	 * async-signal-safe 约束：只能调用 write、_exit、signal 等少数函数，
58	 * 严禁调用 malloc/printf/mutex_lock 等非 async-signal-safe 函数。
59	 * 这里只做一件事：向 pipe 写 1 字节，让 poll 立即返回。
60	 */
61	static void looper_signal_handler(int signum) {
62	    if (s_stop_pipe[1] >= 0) {
63	        char c = 1;
64	        (void)write(s_stop_pipe[1], &c, 1);  // 忽略返回值（pipe 满时丢弃）
65	    }
66	}
67	
68	// ---- Looper 单例实现 ----
69	
70	/**
71	 * @brief 获取当前线程的 Looper 实例（懒汉构造）
72	 *
73	 * 首次调用时通过 Looper::create() 生成实例存入 thread_local，
74	 * 后续调用直接返回缓存指针。
75	 */
76	Looper* Looper::current() {
77	    if (!t_looper) t_looper = Looper::create();
78	    return t_looper.get();
79	}
80	
81	/// 将 D-Bus 连接对象绑定到 Looper（Looper 不拥有 conn_ 的所有权）
82	void Looper::attach(DBusConnection* conn) {
83	    conn_ = conn;
84	}
85	
86	/**
87	 * @brief 启动 D-Bus 事件主循环（阻塞直到收到退出信号）
88	 *
89	 * @param ctx  ServerContext 生命周期句柄；ctx->running 为退出条件
90	 *
91	 * 执行顺序：
92	 *   1. 验证 conn_ 非空，否则报错返回
93	 *   2. 创建 self-pipe（失败则降级到 timeout 模式）
94	 *   3. 注册 SIGTERM/SIGINT signal handler（通过 sigaction）
95	 *   4. 进入 poll 循环（或降级的 timeout 循环）
96	 *   5. 收到退出条件后清理 pipe fd，正常返回
97	 *
98	 * 退出条件（任一满足）：
99	 *   - ctx->running.store(false)（外部请求退出）
100	 *   - poll 返回错误（非 EINTR）
101	 *   - dbus_connection_read_write_dispatch 返回 false（连接丢失）
102	 *   - Logger::stopRequested()（timeout 模式下，signal handler 标记）
103	 */
104	void Looper::run(ServerContext* ctx) {
105	    // ---- 前置检查 ----
106	    if (!conn_) {
107	        LOG_ERROR(LogModule::DBUS, "Looper::run: no connection attached");
108	        return;
109	    }
110	
111	    // ---- 创建 self-pipe ----
112	    // pipe() 失败（EMFILE 或 ENFILE）时设为 -1，后续走降级路径
113	    if (pipe(s_stop_pipe) < 0) {
114	        LOG_ERROR(LogModule::DBUS, "Looper::run: pipe() failed, falling back to timeout mode");
115	        s_stop_pipe[0] = s_stop_pipe[1] = -1;
116	    } else {
117	        // 两端均设 O_NONBLOCK：
118	        // - 读端：排空循环用 `while (read(...) > 0)` 清空管道，阻塞模式下管道清空后
119	        //   第二次 read 会永久挂起（SIGTERM 后主线程卡死在 pipe_read，systemd 只能
120	        //   等 TimeoutStopSec 后 SIGKILL）。
121	        // - 写端：signal handler 中的 write 不因管道满而阻塞（async-signal-safe 约束）。
122	        for (int& fd : s_stop_pipe) {
123	            const int flags = fcntl(fd, F_GETFL, 0);
124	            if (flags >= 0) (void)fcntl(fd, F_SETFL, flags | O_NONBLOCK);
125	        }
126	    }
127	
128	    // ---- 注册信号处理器 ----
129	    // 不设 SA_RESTART：让被信号中断的系统调用返回 EINTR 而不是自动重入，
130	    // 这样 dbus_connection_read_write_dispatch 能及时返回让我们检查退出条件
131	    struct sigaction sa = {};
132	    sa.sa_handler = looper_signal_handler;
133	    sa.sa_flags = 0;
134	    sigemptyset(&sa.sa_mask);
135	    sigaction(SIGTERM, &sa, nullptr);
136	    sigaction(SIGINT, &sa, nullptr);
137	
138	    // ---- 获取 D-Bus socket fd ----
139	    int dbus_fd = -1;
140	    dbus_connection_get_socket(conn_, &dbus_fd);
141	
142	    LOG_INFO(LogModule::DBUS, "Looper::run: entering event loop");
143	
144	    // ---- poll 模式（推荐） ----
145	    // 同时监听 D-Bus 消息 fd 和 signal pipe；100ms 超时快速响应状态变化
146	    if (s_stop_pipe[0] >= 0 && dbus_fd >= 0) {
147	        struct pollfd fds[2];
148	        fds[0].fd = dbus_fd;          // 索引 0：D-Bus fd
149	        fds[0].events = POLLIN;
150	        fds[1].fd = s_stop_pipe[0];   // 索引 1：signal pipe 读端
151	        fds[1].events = POLLIN;
152	
153	        while (ctx->running.load()) {
154	            // 100ms 超时：既保证及时收到信号，又定期检查 ctx->running
155	            int ret = poll(fds, 2, 100);
156	            if (ret < 0) {
157	                if (errno == EINTR) continue;  // 信号中断，重试
158	                LOG_ERROR(LogModule::DBUS, "Looper::run: poll() error");
159	                break;
160	            }
161	            if (ret == 0) continue;  // 超时无事件，回去检查 running flag
162	
163	            // 收到退出信号（signal handler 写入）
164	            if (fds[1].revents & POLLIN) {
165	                char buf[8];
166	                // 循环 read 直到 pipe 清空（pipe 缓冲区可能有多字节积压）
167	                while (read(s_stop_pipe[0], buf, sizeof(buf)) > 0) {}
168	                LOG_INFO(LogModule::DBUS, "Looper::run: received stop signal");
169	                ctx->running.store(false);
170	                break;
171	            }
172	
173	            // D-Bus fd 可读：单次非阻塞派发
174	            // 注意：dbus_connection_read_write_dispatch(conn_, 0) 的返回值语义是
175	            // “连接未断开”而不是“还有数据”——无界 while 会把主循环永久卡死在这里：
176	            //   1. self-pipe 停止信号永远得不到检查，SIGTERM/SIGINT 失效
177	            //      （systemd 停服只能等 TimeoutStopSec 后 SIGKILL，journal 可见 stop timeout）
178	            //   2. 主线程空转，单核 CPU 接近 100%
179	            //   3. 切换到系统总线后该问题必现（原会话总线场景同样存在，只是未暴露）
180	            // 因此每次 POLLIN 只派发一次；若仍有数据到达，poll 会立即再次唤醒。
181	            if (fds[0].revents & POLLIN) {
182	                (void)dbus_connection_read_write_dispatch(conn_, 0);
183	            }
184	        }
185	    } else {
186	        // ---- 降级模式 ----
187	        // pipe 创建失败或 dbus_fd 无效时的兜底：依赖 dbus 内部 1 秒超时
188	        // 退出条件额外检查 Logger::stopRequested()（signal handler 设置的 flag）
189	        while (ctx->running.load() && !Logger::stopRequested()) {
190	            if (!dbus_connection_read_write_dispatch(conn_, 1000)) {
191	                LOG_ERROR(LogModule::DBUS, "Looper::run: D-Bus connection lost");
192	                break;
193	            }
194	        }
195	        if (Logger::stopRequested()) ctx->running.store(false);
196	    }
197	
198	    // ---- 清理 ----
199	    if (s_stop_pipe[0] >= 0) { close(s_stop_pipe[0]); s_stop_pipe[0] = -1; }
200	    if (s_stop_pipe[1] >= 0) { close(s_stop_pipe[1]); s_stop_pipe[1] = -1; }
201	
202	    LOG_INFO(LogModule::DBUS, "Looper::run: event loop exited");
203	}
204	
205	}  // namespace weaknet_dbus
